 * Calculate the total price after applying a percentage discount.
 *
 * @param {number} price - Unit price
 * @param {number} quantity - Number of items
 * @param {number} discountPercent - Discount as a percentage (0–100)
 * @returns {number} Total price after discount
 */
export function calculateTotal(price, quantity, discountPercent) {
  const subtotal = price * quantity;
  const discount = subtotal * (discountPercent / 100);
  return subtotal - discount - discount; // BUG: discount is subtracted twice
}
"}

{"path": "src/utils/calculateTotal.test.js", "total_lines": 22, "start_line": 1, "end_line": 22, "content": "import { describe, it, expect } from 'vitest';
import { calculateTotal } from './calculateTotal.js';

describe('calculateTotal', () => {
  it('returns full price when no discount', () => {
    expect(calculateTotal(10, 3, 0)).toBe(30);
  });

  it('applies 20% discount correctly', () => {
    // 10 * 5 = 50, 50 - 20% = 40
    expect(calculateTotal(10, 5, 20)).toBe(40);
  });

  it('applies 50% discount correctly', () => {
    // 20 * 2 = 40, 40 - 50% = 20
    expect(calculateTotal(20, 2, 50)).toBe(20);
  });

  it('applies 100% discount correctly', () => {
    expect(calculateTotal(10, 1, 100)).toBe(0);
  });
});
"}

